<script setup>
import { computed, reactive, watch } from 'vue'
const props = defineProps({ cita: { type: Object, default: null }, catalogos: { type: Object, required: true }, loadingCatalogos: Boolean, catalogError: String, busy: Boolean, errors: { type: Object, default: () => ({}) }, readonly: Boolean })
const emit = defineEmits(['save','cancel'])
const blank = () => ({ CodigoPaciente:'', CodigoColaborador:'', CodigoSucursal:'', CodigoEspecialidad:'', FechaHoraCita:'', TipoAtencion:'Consulta', MotivoConsulta:'', Sintomas:'', ObservacionesMedicas:'', TratamientoGeneral:'', PresionArterial:'', Temperatura:'', Peso:'', Estado:'Programada', detalles:[] })
const form = reactive(blank())
watch(() => props.cita, value => { Object.assign(form, blank(), value ? { ...value, FechaHoraCita: (value.FechaHoraCita || '').slice(0,16), detalles: (value.detalles || []).map(d => ({...d})) } : {}) }, { immediate:true })
const catalogEmpty = computed(() => ['pacientes','sucursales','colaboradores','especialidades'].some(k => !props.catalogos[k]?.length))
function addDetail(){ form.detalles.push({ TipoDetalle:'Indicacion', SubtipoDetalle:'', DescripcionDetalle:'', Dosis:'', Frecuencia:'', Duracion:'', Indicaciones:'', Resultado:'', Cantidad:'' }) }
function removeDetail(i){ form.detalles.splice(i,1) }
function submit(){ const payload = {...form, Temperatura: form.Temperatura === '' ? null : Number(form.Temperatura), Peso: form.Peso === '' ? null : Number(form.Peso), FechaHoraCita: form.FechaHoraCita, detalles: form.detalles.map(d=>({...d, Cantidad:d.Cantidad === '' ? null : (d.Cantidad == null ? null : Number(d.Cantidad)), FechaRegistro:d.FechaRegistro || new Date().toISOString(), Estado:d.Estado || 'Activo', CodigoProducto:d.CodigoProducto || null})) }; emit('save',payload) }
function err(k){ return props.errors[k]?.join(' ') || '' }
</script>
<template><form class="cita-form" @submit.prevent="submit"><div v-if="Object.keys(errors).length" class="cita-error" role="alert"><p v-for="(messages,key) in errors" :key="key">{{ key }}: {{ messages.join(' ' ) }}</p></div><p v-if="loadingCatalogos" class="cita-note">Cargando catálogos…</p><p v-else-if="catalogError" class="cita-error" role="alert">{{ catalogError }}</p><p v-else-if="catalogEmpty" class="cita-note">Uno o más catálogos están vacíos. Selecciona una opción disponible o contacta al administrador.</p>
 <div class="cita-form-grid">
  <label>Paciente *<select v-model="form.CodigoPaciente" required :disabled="readonly || busy || !catalogos.pacientes?.length"><option value="">Selecciona paciente</option><option v-for="p in catalogos.pacientes" :key="p.id" :value="p.id">{{ p.Nombres }} {{ p.Apellidos }} · {{ p.NumeroExpediente }}</option></select><small class="cita-field-error">{{ err('CodigoPaciente') }}</small></label>
  <label>Colaborador *<select v-model="form.CodigoColaborador" required :disabled="readonly || busy || !catalogos.colaboradores?.length"><option value="">Selecciona colaborador</option><option v-for="p in catalogos.colaboradores" :key="p.id" :value="p.id">{{ p.NombreCompleto || `${p.Nombres} ${p.Apellidos}` }}</option></select><small class="cita-field-error">{{ err('CodigoColaborador') }}</small></label>
  <label>Sucursal *<select v-model="form.CodigoSucursal" required :disabled="readonly || busy || !catalogos.sucursales?.length"><option value="">Selecciona sucursal</option><option v-for="s in catalogos.sucursales" :key="s.id || s._id" :value="s.id || s._id">{{ s.nombre || s.NombreSucursal }}</option></select><small class="cita-field-error">{{ err('CodigoSucursal') }}</small></label>
  <label>Especialidad *<select v-model="form.CodigoEspecialidad" required :disabled="readonly || busy || !catalogos.especialidades?.length"><option value="">Selecciona especialidad</option><option v-for="e in catalogos.especialidades" :key="e.id" :value="e.id">{{ e.NombreEspecialidad }}<template v-if="e.Descripcion"> — {{ e.Descripcion }}</template></option></select><small class="cita-field-error">{{ err('CodigoEspecialidad') }}</small></label>
  <label>Fecha y hora *<input v-model="form.FechaHoraCita" type="datetime-local" required :disabled="readonly || busy"><small class="cita-field-error">{{ err('FechaHoraCita') }}</small></label>
  <label>Tipo de atención *<input v-model.trim="form.TipoAtencion" maxlength="30" required :disabled="readonly || busy"><small class="cita-field-error">{{ err('TipoAtencion') }}</small></label>
  <label>Estado *<select v-model="form.Estado" required :disabled="readonly || busy"><option>Programada</option><option>Confirmada</option><option>En curso</option><option>Atendida</option><option>Cancelada</option><option>No asistió</option></select><small class="cita-field-error">{{ err('Estado') }}</small></label>
  <label class="cita-wide">Motivo de consulta *<textarea v-model.trim="form.MotivoConsulta" maxlength="500" rows="2" required :disabled="readonly || busy"/><small class="cita-field-error">{{ err('MotivoConsulta') }}</small></label>
  <label>Síntomas<textarea v-model.trim="form.Sintomas" maxlength="1000" rows="2" :disabled="readonly || busy"/></label><label>Observaciones médicas<textarea v-model.trim="form.ObservacionesMedicas" maxlength="1000" rows="2" :disabled="readonly || busy"/></label><label class="cita-wide">Tratamiento general<textarea v-model.trim="form.TratamientoGeneral" maxlength="1000" rows="2" :disabled="readonly || busy"/></label><label>Presión arterial<input v-model.trim="form.PresionArterial" maxlength="20" :disabled="readonly || busy"></label><label>Temperatura<input v-model="form.Temperatura" type="number" min="0" max="999.99" step="0.01" :disabled="readonly || busy"></label><label>Peso<input v-model="form.Peso" type="number" min="0" max="9999.99" step="0.01" :disabled="readonly || busy"></label>
 </div>
 <section class="cita-details"><div class="cita-section-head"><h3>Detalle de la consulta</h3><button v-if="!readonly" type="button" :disabled="busy" @click="addDetail">+ Agregar detalle</button></div><p v-if="!form.detalles.length" class="cita-note">No hay líneas de detalle. Puedes agregar indicaciones, medicamentos o resultados.</p><article v-for="(d,i) in form.detalles" :key="i" class="cita-detail-row"><div class="cita-detail-title"><strong>Detalle {{ i+1 }}</strong><button v-if="!readonly" type="button" class="cita-danger-outline" :disabled="busy" @click="removeDetail(i)">Quitar</button></div><div class="cita-form-grid"><label>Tipo *<input v-model.trim="d.TipoDetalle" maxlength="40" required :disabled="readonly || busy"></label><label>Subtipo<input v-model.trim="d.SubtipoDetalle" maxlength="100" :disabled="readonly || busy"></label><label class="cita-wide">Descripción *<textarea v-model.trim="d.DescripcionDetalle" maxlength="1000" required rows="2" :disabled="readonly || busy"/></label><label>Dosis<input v-model.trim="d.Dosis" maxlength="100" :disabled="readonly || busy"></label><label>Frecuencia<input v-model.trim="d.Frecuencia" maxlength="100" :disabled="readonly || busy"></label><label>Duración<input v-model.trim="d.Duracion" maxlength="100" :disabled="readonly || busy"></label><label>Cantidad<input v-model="d.Cantidad" type="number" min="0" step="0.01" :disabled="readonly || busy"></label><label class="cita-wide">Indicaciones<textarea v-model.trim="d.Indicaciones" maxlength="500" rows="2" :disabled="readonly || busy"/></label><label class="cita-wide">Resultado<textarea v-model.trim="d.Resultado" maxlength="1000" rows="2" :disabled="readonly || busy"/></label></div></article></section>
 <div class="cita-form-actions"><button type="button" :disabled="busy" @click="emit('cancel')">{{ readonly ? 'Cerrar' : 'Cancelar' }}</button><button v-if="!readonly" class="cita-primary" :disabled="busy || loadingCatalogos || !!catalogError || !catalogos.pacientes?.length || !catalogos.sucursales?.length || !catalogos.colaboradores?.length || !catalogos.especialidades?.length">{{ busy ? 'Guardando…' : 'Guardar cita' }}</button></div>
</form></template>
